require_once __DIR__.'/inc/bootstrap.php';require_once __DIR__.'/inc/legal_center.php';$pdo=db();$type=isset($_GET['doc'])?(string)$_GET['doc']:'terms';$types=tickex_legal_types();if(!isset($types[$type]))abort_404('Documento no encontrado.');$doc=tickex_legal_public_document($pdo,$type);$title=$types[$type];$hideNav=true;include __DIR__.'/inc/layout_top.php';
?><style>.legal-page{max-width:860px;margin:0 auto}.legal-hero{padding:28px;background:linear-gradient(135deg,#171b38,#34236b)}.legal-hero h1{margin:5px 0}.legal-kicker{color:#5edbef;font-size:11px;text-transform:uppercase;font-weight:900;letter-spacing:.12em}.legal-body{white-space:pre-wrap;line-height:1.75}.legal-tabs{display:flex;gap:7px;flex-wrap:wrap;margin:15px 0}.legal-tabs a{padding:8px 11px;border:1px solid var(--line);border-radius:10px;text-decoration:none;color:inherit}.legal-tabs a.active{border-color:#765ce8;background:rgba(118,92,232,.15)}</style><main class="legal-page"><section class="card legal-hero"><div class="legal-kicker">Información legal</div><h1><?php echo e($types[$type]);?></h1><?php if($doc):?><p>Versión <?php echo (int)$doc['version'];?> · vigente desde <?php echo e(date('d/m/Y',strtotime($doc['effective_at'])));?></p><?php endif;?></section><nav class="legal-tabs"><?php foreach(array('terms','privacy','refunds') as $key):?><a class="<?php echo $key===$type?'active':'';?>" href="legal.php?doc=<?php echo e($key);?>"><?php echo e($types[$key]);?></a><?php endforeach;?><a href="arrepentimiento.php">Botón de arrepentimiento</a></nav><section class="card"><?php if(!$doc):?><h2>Documento en preparación</h2><p class="muted">Esta versión todavía no fue publicada. Para consultas, comunicate con el soporte de Tickex.</p><?php else:?><p class="muted"><?php echo e($doc['summary']);?></p><div class="legal-body"><?php echo e($doc['body']);?></div><?php endif;?></section></main><?php include __DIR__.'/inc/layout_bottom.php';?>
